Fixpoint c4_offsets (off : nat) (cs : list cell) : list nat :=
  match cs with
  | [] => []
  | C4 _ :: r => off :: c4_offsets (off + 4) r
  | c :: r => c4_offsets (off + csize c) r
  end.

Ltac kx_word4_try segs zv xs m a v b c A cs H ks :=
  lazymatch ks with
  | nil => fail
  | cons ?k ?rest =>
      first [ eapply (zk_word4_ok segs zv xs m a v b c A cs k _);
              [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
              | kx_arith | kx_arith | kx_arith | kx_arith | exact H | reflexivity
              | cbv [zden nth]; lia | cbv [zden nth]; f_equal; first [reflexivity | lia] ]
            | kx_word4_try segs zv xs m a v b c A cs H rest ]
  end.

(* [comment removed for export] *)
Ltac kx_word4 :=
  lazymatch goal with
  | |- kentry_ok ?segs (kE ?zv ?xs) ?m (zk_ent (ZKWord ?a 4 ?v)) =>
      let s1 := eval vm_compute in (zsa a) in
      lazymatch s1 with SA ?b ?c =>
        match goal with H : rw_cells segs m ?A ?cs |- _ =>
          let ks := eval vm_compute in (c4_offsets 0 cs) in
          kx_word4_try segs zv xs m a v b c A cs H ks end
      end
  end.

Ltac kx_bvrange :=
  try (match goal with |- 0 <= bv_unsigned ?w < 2 ^ 64 =>
         let HH := fresh in pose proof (bv_unsigned_in_range 64 w) as HH; unfold bv_modulus in HH; cbn in HH; lia end).

